import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第72章 从头到尾","description":"","frontmatter":{},"headers":[],"relativePath":"第72章_从头到尾.md","filePath":"第72章_从头到尾.md"}'),_={name:"第72章_从头到尾.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第72章-从头到尾" tabindex="-1">第72章 从头到尾 <a class="header-anchor" href="#第72章-从头到尾" aria-label="Permalink to &quot;第72章 从头到尾&quot;">​</a></h1><p>三月有一晚，她把家里的事从头讲了一遍。</p><p>那次是她自己起的头，起因特别小。</p><p>那天我在讲我们家过年怎么贴对联，讲我爸每年把&quot;福&quot;字贴歪。</p><p>我讲完，她隔了很久。</p><p>然后她说，我们家没有贴过对联。</p><p>我说，为什么。</p><p>她说，我们家过年没人管那个。</p><p>她说，我妈那几年过年都在上班。</p><p>她说，收银的年三十最忙。</p><p>我说，那你爸呢。</p><p>她说，我爸那几年不在。</p><p>她说，他跑长途，一年回来两次。</p><p>她说，我从来没跟你讲过我爸。</p><p>我说，我知道他跑长途。</p><p>她说，你不知道。</p><p>她说，你不知道的是他哪一年回来的少。</p><p>我说，那你今天讲吗。</p><p>她说，我今天讲。</p><p>她说，我今天讲是因为我今天把作品集第一稿交了，我坐在这儿，我不想干别的。</p><p>她说，我想讲一遍。</p><p>她说，我讲的时候你别打断我，你别问我，你别安慰。</p><p>我说，好。</p><p>她说，你答应得太快了。</p><p>我说，那我不答应，我就在这儿听着。</p><p>她从晚上十一点，讲到凌晨四点二十。</p><p>我这边凌晨四点二十，她那边是前一天晚上九点二十。</p><p>她讲了一整晚。</p><p>她讲的是什么呢，我按她的顺序记下来。</p><p>第一段，她讲她小时候住的那个地方搬了三次。</p><p>她说第一次搬是她四岁，因为她爸那辆车押出去了。</p><p>她说第二次搬是她八岁，因为那条街要修。</p><p>她说第三次搬是她自己考上了市里的高中，她妈在她们学校附近租了一个单间。</p><p>她说，那个单间我住了三年。</p><p>她说，单间只有一张床，一张桌，一个电磁炉。</p><p>她说，我每天早上五点起来在电磁炉上煮面，煮完把汤喝完，怕倒掉可惜。</p><p>她说，我早上那碗面我吃了三年。</p><p>第二段，她讲她妈。</p><p>她说，我妈这个人，她不发脾气。</p><p>我说，那她干什么。</p><p>她说，她哭。</p><p>她说，她一哭就说一句，她说&quot;我这辈子都给你了&quot;。</p><p>她说，她每次说这句，我就不能说任何&quot;我不要&quot;。</p><p>她说，我八岁的时候跟她说过一次我不要去那个补习班。</p><p>她说，她当天晚上躺在床上，说她这辈子都给我了，她身体不好。</p><p>她说，她从那天以后每次我要说什么，她就先把这句话摆出来。</p><p>她说，我这一辈子最怕的不是她骂我。</p><p>她说，我怕她躺下去。</p><p>我说，那你现在还敢跟她说不吗。</p><p>她说，我现在连&quot;我今天累了&quot;都不说。</p><p>她说，我说&quot;我累了&quot;，她要问我为什么累，我要解释，我解释完我比干活还累。</p><p>她说，所以我从来不说我累。</p><p>第三段，她讲她爸。</p><p>这一段很短。</p><p>她说，我爸回来的那一年我上初二。</p><p>她说，他回来那天我在家里，我在写题。</p><p>她说，我开门以后我愣了。</p><p>她说，我愣那一下，他就看见了。</p><p>她说，他这辈子没跟我说过一句话，因为那一下。</p><p>她说，从那以后他回来我都得打招呼，我打得很好，我笑得很好。</p><p>她说，可是我心里那一下，我永远收不回来。</p><p>她说，我不恨他。</p><p>她说，我只是有时候想，我要是那天没开门就好了。</p><p>第四段，她讲她为什么开始省钱。</p><p>她说，高一有一次学校要交一笔钱，八百。</p><p>她说，我妈在家里翻了一个钟头。</p><p>她说，我妈翻完跟我说，明天给你。</p><p>她说，那天晚上我在阳台上，我看见我妈在跟一个人打电话。</p><p>她说，她在借钱。</p><p>她说，她借的是她一个表弟的，一百一百地借。</p><p>她说，我那时候站在阳台上，我心里就想了一件事。</p><p>我说，什么事。</p><p>她说，我以后要自己挣钱。</p><p>她说，从那以后我要任何东西，我先算我妈要翻多久。</p><p>第五段，她讲了她为什么退学。</p><p>这一段她讲得最慢。</p><p>她说，我那年不是读不下去。</p><p>她说，我那次的分我够了。</p><p>她说，我是那天在办公室里，我看见那个老师给我妈打电话，她一边打一边看表。</p><p>她说，她说&quot;这个孩子心理有问题，家长要多关注&quot;。</p><p>她说，我妈在旁边站着，她一直说好，一直点头。</p><p>她说，我妈那时候腰不好，她站了二十分钟。</p><p>她说，我推门进去的时候我妈在走廊里扶那个墙。</p><p>她说，她扶那个墙她在笑。</p><p>她说，她跟我笑着说没事，老师说你挺好的。</p><p>她说，那天我回去我就决定我不念了。</p><p>她说，我要是继续念，我要我妈再扶二十次墙。</p><p>我说，你从来没跟我讲过这段。</p><p>她说，我从来没跟任何人讲过。</p><p>她说，我今天讲完了。</p><p>那晚她讲完是四点二十。</p><p>她说，我今天讲了五个小时。</p><p>我说，嗯。</p><p>她说，你今天真的一句话没问。</p><p>我说，你说了别问。</p><p>她说，那你现在在想什么。</p><p>我说，我在想你今天讲完会不会更难受。</p><p>她说，不会。</p><p>她说，我今天讲完我很清楚。</p><p>她说，我第一次把这些排成一个顺序。</p><p>她说，我发现这里面没有一件事是我做错的。</p><p>她说，你看，我这一辈子第一次承认不是我要承认，是我算出来的。</p><p>我说，那你现在什么感觉。</p><p>她隔了很久。</p><p>然后她说了一句让我不敢接的话。</p><p>她说，我今天跟你讲这些，你听完不要对我更好。</p><p>我说，为什么。</p><p>她说，因为你一对我更好，我就得还。</p><p>她说，我还不起。</p><p>她说，你对我好这件事，我这一辈子只有一个人我不用还。</p><p>我说，谁。</p><p>她说，我妹妹。</p><p>她说，因为我给她买东西我不用她还。</p><p>她说，所以你今天要是对我特别好，我们俩就完了。</p><p>我说，那我不。</p><p>她说，你别答应。</p><p>我说，我说的是，我今天不。</p><p>她说，那明天呢。</p><p>我没回。</p><p>那天早上七点，我迟到了。</p><p>我在走廊上跑，我跑过楼梯口的时候，我脑子里全是那句&quot;我怕她躺下去&quot;。</p><p>我那天第一节是早八，我坐在最后一排，老师讲什么我一个字没进去。</p><p>我在算一件很没用的事。</p><p>我在算她那天晚上讲了五个小时，她那边的白天她睡了几小时。</p><p>我算出来她睡了不到三个小时。</p><p>她那天上午有课。</p><p>我十点给她发了一条。</p><p>我说，你今天有课，你去睡。</p><p>她十二点回。</p><p>她回的是：我今天翘了。</p><p>她说：你别学我。</p><p>我说：我学不到。</p><p>她说：那你昨晚睡了吗。</p><p>我说：四点二十。</p><p>她说：你看，你也是一个会翘课的人。</p><p>那天我什么都没说。</p><p>我把她那天讲的五个小时，用两天抄了一遍。</p><p>抄完我把它单独放进一个本子。</p><p>那个本子我从来没有拿给她看过。</p><p>我一直没告诉她：她那一晚讲的话，比她说过的所有好听的话加起来都重要，而我一句也没丢。</p>',140)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
